stages.sampleAnswer:
- Article: { id, title, content, sourceId, sourceUrl, publishedAt, category, contentHash }
- NewsSource: { id, name, feedUrl, fetchInterval, lastFetchedAt }
- Category: { id, name }
- ArticleMetadata: { articleId, keywords, imageUrl, summary }

GET /articles/feed
  query: { category?, sourceId?, limit=20, cursor? }
  → 200 { articles: Article[], nextCursor, totalCount }

GET /articles/search
  query: { q: string, category?, limit=20, offset=0 }
  → 200 { articles: Article[], totalCount }

GET /sources
  → 200 { sources: NewsSource[] }
